/**
 * Shared figure-export types. Source of truth: backend Pydantic models in
 * routes/saved_features/models.py — regenerated by `npm run sync-types`.
 */
import type { components } from '../api-types';

export type FigureExportFormat = components['schemas']['TransectFigureRequest']['fmt'];

export type FigureXAxis = components['schemas']['TransectFigureRequest']['x_axis'];

/** Backend value — actually sent. */
export type ApiBasemapSource = components['schemas']['TransectFigureRequest']['basemap_source'];

/** UI-side superset: `'none'` is a frontend sentinel meaning "don't include a basemap". */
export type BasemapSource = ApiBasemapSource | 'none';
